// PreToolUse Bash hook — enforces IceSpiritAI_Vision commit hygiene.
//
// Receives JSON on stdin:
//   { "tool_name": "Bash", "tool_input": { "command": "..." } }
//
// Blocks:
//   1. `git add -A` / `git add .` — CLAUDE.md requires explicit paths only.
//   2. Any git command that references a sensitive file:
//        - gradle.token.properties (Gitea PAT)
//        - ~/.gradle/gradle.properties (release signing creds)
//        - local.properties (SDK path)
//   3. Destructive ops on `app/libs/*.aar` — PaddleOCR SDK is ~70 MB and not
//      regenerated by every build; `ice_ocr_rules` profile silently breaks
//      without it. Must run `tools/build-ppocr-sdk.sh` to regenerate.
//
// On block: exit 2 with a stderr message Claude Code surfaces to the user.
// On allow: exit 0 with no output.

let input = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (chunk) => { input += chunk; });
process.stdin.on('end', () => {
  let cmd = '';
  try {
    const data = JSON.parse(input);
    cmd = (data.tool_input && typeof data.tool_input.command === 'string')
      ? data.tool_input.command
      : '';
  } catch (_e) {
    // Malformed JSON → fail open (do not block legitimate work).
    process.exit(0);
  }

  if (!cmd) process.exit(0);

  // Rule 1: `git add -A` / `git add --all` / `git add .` / `git add ./`
  //   / `git add ..` / `git add .git` / `git add *` (must catch shell
  //   continuations like `git add -A; echo done`, `git add . && git status`,
  //   and global flags between `git` and `add` like `git -C . add -A` or
  //   `git --git-dir=x add -A`).
  // Bypass cases the regex now covers (verified v0.1.43 self-test):
  //   - shell continuations (`;`, `&&`, `||`, `|`, newline) before/after
  //     `git add ...`
  //   - commands embedded after leading whitespace
  //   - global git flags (`-C x`, `--git-dir=foo`, `-c x=y`) between
  //     `git` and `add`
  //   - `--all` long form (functionally identical to `-A`)
  //   - `./`, `..`, `.git` bare dot variants (all stage cwd or .git dir)
  //   - bare `*` glob (caller's intent was "add everything")
  // The capture group `(?:\s+\S+)*` allows any number of whitespace+token
  // groups between `git` and `add` (i.e. global flags), so `git -C foo add`
  // and `git --git-dir=bar add` are caught. The lookahead on `.`
  // (`[\s\/.;&|*]|$`) expands the previous regex's separator set to also
  // include `/`, `*`, and `.` so `git add ./`, `git add ../foo`, and
  // `git add .git` are blocked.
  if (/(?:^|;|\s|\|\||&&|\|)\s*git(?:\s+\S+)*\s+add\s+(?:-A\b|--all\b|\.(?=[\s\/.;&|*]|$)|\.\.\b|\.git\b|\*(?=[\s;|&]|$))/m.test(cmd)) {
    console.error(
      'BLOCKED by IceSpiritAI_Vision PreToolUse hook:\n' +
      '  CLAUDE.md requires explicit file paths in `git add`, not `git add -A` or `git add .`.\n' +
      '  List each file path explicitly: `git add path/to/file1 path/to/file2 ...`\n' +
      '  Original command: ' + cmd.split('\n')[0],
    );
    process.exit(2);
  }

  // Rule 2: git operations referencing sensitive files
  const sensitive = /(gradle\.token\.properties|~?\/?\.gradle\/gradle\.properties|local\.properties)/;
  const gitOp = /\b(add|commit|stash|restore|checkout|reset|rm|apply)\b/;
  if (sensitive.test(cmd) && gitOp.test(cmd)) {
    console.error(
      'BLOCKED by IceSpiritAI_Vision PreToolUse hook:\n' +
      '  The command references a sensitive file (Gitea PAT / release signing creds / SDK path).\n' +
      '  These files are gitignored per .gitignore and must NEVER be staged or committed.\n' +
      '  If you need to rotate the Gitea PAT or release signing creds, edit ~/.gradle/gradle.properties (gitignored) directly.\n' +
      '  Original command: ' + cmd.split('\n')[0],
    );
    process.exit(2);
  }

  // Rule 3: destructive ops on app/libs/*.aar (PaddleOCR SDK) or the
  //   app/libs/ directory itself. Match either forward-slash (bash) or
  //   back-slash (cmd/PowerShell) paths, any .aar filename under app/libs/,
  //   the `*.aar` glob pattern, OR a destructive op on app/libs/ as a
  //   directory. `ppocr-sdk.aar` is the only AAR currently committed (~70 MB),
  //   but future AARs added under app/libs/ must also be guarded — the
  //   regex matches any `.aar` filename under app/libs/, not just the
  //   current one.
  const aarFile = /app[\\/]+libs[\\/]+(?:\*|[\w\-.]*\.aar)/;
  const appLibsDir = /app[\\/]+libs[\\/](?=\s|$|\*|;|&|\|)/;
  const destructive = /\b(rm|del|rm\s+-rf|rm\s+-r|rmdir|unlink|mv|git\s+rm|truncate|find\b[^\n]*-delete)\b/;
  if (destructive.test(cmd) && (aarFile.test(cmd) || appLibsDir.test(cmd))) {
    console.error(
      'BLOCKED by IceSpiritAI_Vision PreToolUse hook:\n' +
      '  The command would delete/move/rm a PaddleOCR SDK AAR in app/libs/.\n' +
      '  ppocr-sdk.aar is ~70 MB and is NOT regenerated by every build. \n' +
      '  ice_ocr_rules profile silently breaks without it (no build error, just missing native + ONNX binding).\n' +
      '  To regenerate, run tools/build-ppocr-sdk.sh first; do not delete the existing AAR.\n' +
      '  Original command: ' + cmd.split('\n')[0],
    );
    process.exit(2);
  }

  process.exit(0);
});